package ru.neverland.townysieges;
import java.util.*;import java.nio.file.*;
public final class CampSupplySmoke {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}interface Action{void run()throws Exception;}static void fails(Action action)throws Exception{try{action.run();}catch(Exception expected){return;}throw new AssertionError();}
 public static void main(String[] args)throws Exception{Path dir=Files.createTempDirectory("camp-supply");Path file=dir.resolve("camp.yml");var ledger=new CampSupplyLedger(file);UUID town=UUID.randomUUID(),camp=UUID.randomUUID(),shipment=UUID.randomUUID(),war=UUID.randomUUID();var cargo=new CampSupplyLedger.Receipt(town,camp,Map.of("BREAD",20L,"IRON_INGOT",10L));check(ledger.receive(shipment,cargo)&&ledger.receive(shipment,cargo),"idempotent credit");check(ledger.state().stock().get(town).get("BREAD")==20,"duplicate shipment not doubled");fails(()->ledger.receive(shipment,new CampSupplyLedger.Receipt(town,camp,Map.of("BREAD",21L))));var physical=new CampSupplyLedger.Funding(war,town,0,"CARGO","PAID",Map.of("BREAD",2L,"IRON_INGOT",1L));ledger.funding(physical,true);check(ledger.state().stock().get(town).get("BREAD")==18&&ledger.state().funding().get(war).state().equals("PAID"),"stock and minute receipt atomic");var planned=new CampSupplyLedger.Funding(war,town,1,"ARMY","PLANNED",Map.of("food",1000L));ledger.funding(planned,false);var restarted=new CampSupplyLedger(file);check(restarted.state().equals(ledger.state()),"all inventory, delivery receipts and pending Army intent restored");check(restarted.state().funding().get(war).id().equals(planned.id()),"external debit replay uses stable id");fails(()->CampSupplyLedger.items(Map.of("DIAMOND",1L)));fails(()->CampSupplyLedger.items(Map.of("BREAD",3456L,"IRON_INGOT",1L)));var before=ledger.state();Files.delete(file);Files.createDirectory(file);Files.writeString(file.resolve("block"),"fixture");fails(()->ledger.funding(planned.paid(),false));check(ledger.state().equals(before),"failed file replacement never publishes receipt");System.out.println("CampSupplySmoke PASS: exact stock, delivery replay, immutable receipts, pending external consumption, restart and disk failure");}
}
